class Solution {
public:
    int maximum69Number (int num) {
        int place = 1;
        int bestPlace = 0;
        int n = num;
        while (n > 0) {
            if (n % 10 == 6) {
                bestPlace = place;
            }
            n /= 10;
            place *= 10;
        }
        return num + 3 * bestPlace;
    }
};
